import{G as e,K as t,at as n,j as r}from"./chunks/framework.DrNIf5Lg.js";var i=JSON.parse(`{"title":"编译工具","description":"","frontmatter":{},"headers":[],"relativePath":"zh/develop/system-build-tools.md","filePath":"zh/develop/system-build-tools.md"}`),a={name:`zh/develop/system-build-tools.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="编译工具" tabindex="-1">编译工具 <a class="header-anchor" href="#编译工具" aria-label="Permalink to “编译工具”">​</a></h1><p>StaticPHP 通过调用原生构建系统来构建 PHP、依赖库、扩展和辅助工具。整个环境可以分为三层：</p><ol><li><strong>宿主机工具</strong>，如 <code>autoconf</code>、<code>cmake</code>、<code>make</code>、<code>patch</code> 以及解析器/代码生成器。</li><li><strong>编译器工具链</strong>，如 Zig、GCC、Clang 或 MSVC。选定的工具链负责提供编译器、链接器、归档器和目标平台环境。</li><li><strong>Package 构建 Executor</strong>，负责应用 StaticPHP 通用的 Autoconf 或 CMake 参数并执行 Package 构建。</li></ol><p>排查问题时需要区分这三层：安装了 <code>cmake</code> 不代表选定的编译器工具链已经初始化；存在编译器也不代表源码生成所需的全部工具已经齐备。</p><h2 id="检查环境" tabindex="-1">检查环境 <a class="header-anchor" href="#检查环境" aria-label="Permalink to “检查环境”">​</a></h2><p>安装 StaticPHP 后，以及修改构建目标或工具链后，都应运行 <code>doctor</code>：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 预构建二进制</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 源码安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>如果允许 StaticPHP 自动安装可修复的缺失项，使用：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auto-fix</span></span></code></pre></div><p>在 Linux 和 macOS 上，自动修复可能调用系统包管理器，并可能需要 <code>sudo</code>。在 Windows 上，StaticPHP 可以安装自己管理的辅助 Package，但不能代替你安装 Visual Studio 或 Git。命令行选项参见 <a href="/zh/guide/cli-reference.html#doctor"><code>doctor</code> 命令参考</a>。</p><p>Doctor 检查与当前所选目标相关。例如，只有选定的工具链和目标需要 Zig 或 musl 时，相关检查才会运行；只有选择对应 LLVM 变体时，才会检查 Homebrew 或 MacPorts LLVM。</p><h2 id="各类工具的用途" tabindex="-1">各类工具的用途 <a class="header-anchor" href="#各类工具的用途" aria-label="Permalink to “各类工具的用途”">​</a></h2><table tabindex="0"><thead><tr><th>工具类别</th><th>示例</th><th>在构建中的作用</th></tr></thead><tbody><tr><td>编译器与 binutils</td><td><code>zig</code>、<code>gcc</code>、<code>g++</code>、<code>clang</code>、<code>cl.exe</code>、<code>ld</code>、<code>link.exe</code>、<code>ar</code>、<code>lib.exe</code>、<code>ranlib</code></td><td>编译和链接 PHP 及依赖库</td></tr><tr><td>Autotools</td><td><code>autoconf</code>、<code>automake</code>、<code>libtoolize</code> / <code>glibtoolize</code>、<code>autopoint</code></td><td>生成 <code>configure</code> 脚本及其辅助文件</td></tr><tr><td>Make 工具</td><td><code>make</code>、<code>nmake.exe</code></td><td>执行生成的 Makefile</td></tr><tr><td>CMake</td><td><code>cmake</code></td><td>配置和构建基于 CMake 的 Package</td></tr><tr><td>源码生成器</td><td><code>bison</code>、<code>re2c</code>、<code>flex</code>、<code>gperf</code></td><td>重新生成解析器、词法分析器和 C/C++ 源码</td></tr><tr><td>依赖元数据</td><td><code>pkg-config</code></td><td>读取 <code>.pc</code> 文件并返回静态编译/链接参数</td></tr><tr><td>源码与归档工具</td><td><code>git</code>、<code>patch</code>、<code>tar</code>、<code>unzip</code>、<code>gzip</code>、<code>bzip2</code>、<code>xz</code>、<code>7za.exe</code></td><td>获取、修补和解压源码归档</td></tr><tr><td>Package 专用工具</td><td><code>nasm</code>、Perl、Go</td><td>在选中相应 Package 时构建 OpenSSL 或 FrankenPHP 等项目</td></tr></tbody></table><p>并非每个 Package 都会使用全部工具。Doctor 会检查通用宿主机基础环境和与目标相关的前置条件；选中具体 Package 时，还可能解析 Go、NASM 或 Perl 等额外工具 Package。</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h2><p><code>LinuxToolCheck</code> 从 <code>/etc/os-release</code> 识别发行版，选择对应发行版家族的基础清单，并检查每个包所提供的命令（或文件）。当前清单如下：</p><table tabindex="0"><thead><tr><th>发行版家族</th><th>检查的包或命令</th></tr></thead><tbody><tr><td>Alpine</td><td><code>make</code>、<code>bison</code>、<code>re2c</code>、<code>flex</code>、<code>gperf</code>、<code>git</code>、<code>autoconf</code>、<code>automake</code>、<code>gettext-dev</code>、<code>tar</code>、<code>unzip</code>、<code>gzip</code>、<code>bzip2</code>、<code>cmake</code>、<code>gcc</code>、<code>g++</code>、<code>patch</code>、<code>binutils-gold</code>、<code>libtoolize</code>、<code>which</code></td></tr><tr><td>Debian / Ubuntu 及默认回退清单</td><td><code>make</code>、<code>bison</code>、<code>re2c</code>、<code>flex</code>、<code>gperf</code>、<code>git</code>、<code>autoconf</code>、<code>automake</code>、<code>autopoint</code>、<code>tar</code>、<code>unzip</code>、<code>gzip</code>、<code>gcc</code>、<code>g++</code>、<code>bzip2</code>、<code>cmake</code>、<code>patch</code>、<code>xz</code>、<code>libtoolize</code>、<code>which</code></td></tr><tr><td>RHEL / Fedora</td><td><code>perl</code>、<code>make</code>、<code>bison</code>、<code>re2c</code>、<code>flex</code>、<code>gperf</code>、<code>git</code>、<code>autoconf</code>、<code>automake</code>、<code>tar</code>、<code>unzip</code>、<code>gzip</code>、<code>gcc</code>、<code>g++</code>、<code>bzip2</code>、<code>cmake</code>、<code>patch</code>、<code>which</code>、<code>xz</code>、<code>libtool</code>、<code>gettext-devel</code>、<code>file</code></td></tr><tr><td>CentOS</td><td>RHEL 清单外加 Perl 的 <code>IPC::Cmd</code> 和 <code>Time::Piece</code> 模块</td></tr><tr><td>Arch / Manjaro</td><td><code>base-devel</code>、<code>cmake</code>、<code>gperf</code></td></tr></tbody></table><p>Doctor 还会检查：</p><ul><li>CMake 版本不低于 3.22。</li><li><code>re2c</code> 版本不低于 1.0.3。</li><li>在 musl 发行版上存在 <code>linux-headers</code>。</li><li>StaticPHP 隔离使用的 <code>pkg-config</code> 已安装且可以执行。</li></ul><p>Linux 默认使用 <code>ZigToolchain</code>。启用 <code>--auto-fix</code> 后，缺少 Zig 时 Doctor 可以安装 StaticPHP 的 <code>zig</code> 工具 Package。在非 musl 宿主机上构建 musl 目标时，Doctor 还会检查该目标所需的 musl 运行时/wrapper。旧式的 <code>MuslToolchain</code> 还要求 <code>/usr/local/musl</code> 下存在 musl 交叉工具链。原生 Alpine 构建不需要这些跨宿主机组件。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>目标字符串和宿主发行版是两个不同概念。glibc 发行版可以通过 Zig 生成 musl 目标，而 <code>*-gnu.*</code> 目标仍会动态链接到指定的 glibc ABI。</p></div><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h2><p>默认编译器工具链是 Xcode 或 Xcode Command Line Tools 提供的系统 Clang。StaticPHP 还要求安装 Homebrew 或 MacPorts 之一，以提供其余构建工具。</p><p>Doctor 当前检查以下命令：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl, make, bison, re2c, flex, gperf, pkg-config, git,</span></span>
<span class="line"><span>autoconf, automake, tar, libtool, unzip, xz, gzip, bzip2,</span></span>
<span class="line"><span>cmake, glibtoolize</span></span></code></pre></div><p>它还要求 GNU Bison 3 或更高版本。如果 <code>/usr/bin/bison</code> 版本过旧，Doctor 会继续搜索 Homebrew 和 MacPorts 路径，并可安装较新的包。在 Apple Silicon 上，StaticPHP 使用的 Homebrew 必须是位于 <code>/opt/homebrew</code> 的原生安装，而不是 <code>/usr/local</code> 下的 Intel 安装。</p><p><code>SPC_USE_LLVM</code> 控制使用的 Clang 变体：</p><table tabindex="0"><thead><tr><th>值</th><th>工具链</th><th>编译器位置</th></tr></thead><tbody><tr><td><code>system</code>（默认）</td><td><code>ClangNativeToolchain</code></td><td>Xcode / Command Line Tools 的 <code>clang</code></td></tr><tr><td><code>brew</code></td><td><code>ClangBrewToolchain</code></td><td>Homebrew 的 <code>opt/llvm/bin</code></td></tr><tr><td><code>port</code></td><td><code>ClangPortsToolchain</code></td><td>MacPorts 的 <code>bin</code>（通常为 <code>/opt/local/bin</code>）</td></tr></tbody></table><p>选择 <code>brew</code> 或 <code>port</code> 时，Doctor 会验证对应 LLVM 安装中是否包含 <code>clang</code>。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h2><p>Windows 当前以 x86-64 为构建目标，并使用两类前置依赖。</p><p>以下组件需要用户自行安装：</p><ul><li>Visual Studio，并勾选 x86/x64 C++ 工具组件。</li><li>Git for Windows，且 <code>patch.exe</code> 可以从 <code>PATH</code> 找到（通常来自 <code>C:\\Program Files\\Git\\usr\\bin</code>）。</li></ul><p>Doctor 可以安装以下由 StaticPHP 管理的基础 Package：</p><table tabindex="0"><thead><tr><th>Package</th><th>用途</th></tr></thead><tbody><tr><td><code>vswhere</code></td><td>查找包含 <code>Microsoft.VisualStudio.Component.VC.Tools.x86.x64</code> 的最新 Visual Studio 安装</td></tr><tr><td><code>msys2-build-essentials</code></td><td>提供 MSYS2，以及 <code>make</code>、Autotools、<code>libtool</code>、<code>pkgconf</code>、Perl、Bison 和 <code>re2c</code></td></tr><tr><td><code>7za-win</code></td><td>解压需要 <code>7za.exe</code> 的格式</td></tr></tbody></table><p><code>nasm</code>、<code>strawberry-perl</code> 等附加工具也已经表示为 Tool Package，但它们会在选中的 Package 通过 <code>tools</code> 声明时安装，并不是无条件运行的 Windows Doctor 检查。</p><p><code>MSVCToolchain</code> 会调用检测到的 Visual Studio 的 <code>vcvarsall.bat x64</code> 并导入其环境。随后 Doctor 会验证 <code>cl.exe</code>、<code>link.exe</code>、<code>lib.exe</code>、<code>dumpbin.exe</code>、<code>msbuild.exe</code> 和 <code>nmake.exe</code>。导入的环境会在 <code>downloads/.vcenv-cache</code> 中缓存最多一小时。</p><p>MSYS2 根目录默认为 <code>pkgroot/.../msys2-build-essentials/msys64</code>。可以通过 <code>SPC_MSYS2_PATH</code> 修改；其值必须指向 <code>msys64</code> 目录。v3 不再使用 v2 的 PHP SDK 目录和 Visual Studio 版本选项。</p><h3 id="frankenphp-所需的-llvm-clang" tabindex="-1">FrankenPHP 所需的 LLVM/Clang <a class="header-anchor" href="#frankenphp-所需的-llvm-clang" aria-label="Permalink to “FrankenPHP 所需的 LLVM/Clang”">​</a></h3><p>常规 Windows PHP 和依赖库构建使用 MSVC。FrankenPHP 是例外：它的 CGO 链接步骤需要 Clang 和 LLD。</p><p>StaticPHP 会优先使用 <code>CC</code> 指定的 Clang 绝对路径；否则通过 <code>vswhere</code> 查找 Visual Studio LLVM 安装中的 <code>VC\\Tools\\Llvm\\x64\\bin\\clang.exe</code>。构建 FrankenPHP 时，请在 Visual Studio Installer 中安装 <strong>C++ Clang tools for Windows</strong> 组件。这个 Clang 依赖不会取代 PHP 和依赖库构建阶段所需的 MSVC。</p><h2 id="编译器工具链选择" tabindex="-1">编译器工具链选择 <a class="header-anchor" href="#编译器工具链选择" aria-label="Permalink to “编译器工具链选择”">​</a></h2><p><code>GlobalEnvManager</code> 会先读取 <code>config/env.ini</code>（以及可选的 <code>config/env.custom.ini</code>），再由 <code>ToolchainManager</code> 初始化选定的工具链。常规选择如下：</p><table tabindex="0"><thead><tr><th>宿主系统</th><th>默认实现</th><th>当前存在的其他实现</th></tr></thead><tbody><tr><td>Linux</td><td><code>ZigToolchain</code></td><td><code>GccNativeToolchain</code>、<code>ClangNativeToolchain</code>、<code>MuslToolchain</code></td></tr><tr><td>macOS</td><td><code>ClangNativeToolchain</code></td><td><code>ClangBrewToolchain</code>、<code>ClangPortsToolchain</code></td></tr><tr><td>Windows</td><td><code>MSVCToolchain</code></td><td>无</td></tr></tbody></table><p>在 Unix 上，工具链会提供 <code>CC</code>、<code>CXX</code>、<code>AR</code>、<code>RANLIB</code> 和 <code>LD</code> 的默认值。调用方已经设置的值优先于 <code>env.ini</code> 默认值。<code>SPC_TARGET</code> 决定目标操作系统/libc/ABI，<code>SPC_USE_LLVM</code> 决定 macOS 的 Clang 分发方式。<code>SPC_TOOLCHAIN</code> 可以覆盖实现类，但它目前是维护者级别的内部设置，并非稳定的公开扩展契约。</p><p>环境初始化后，工具链会验证其命令以及目标/libc 组合。能够识别编译器时，还会把编译器描述记录到 <code>PHP_BUILD_COMPILER</code>。</p><h2 id="隔离的-pkg-config" tabindex="-1">隔离的 pkg-config <a class="header-anchor" href="#隔离的-pkg-config" aria-label="Permalink to “隔离的 pkg-config”">​</a></h2><p>Unix 构建会刻意使用由 StaticPHP 管理的 <code>pkg-config</code>，而不是碰巧位于系统 <code>PATH</code> 首位的可执行文件。<code>PkgConfigUtil</code> 按以下顺序搜索：</p><ol><li><code>pkgroot/&lt;platform&gt;/bin/pkg-config</code></li><li><code>buildroot/bin/pkg-config</code></li></ol><p>Doctor 可以通过 <code>pkg-config</code> 工具 Package 安装预构建版本。如果需要从源码构建，StaticPHP 会使用其内置 GLib 构建 pkg-config，并禁用系统 include、library、sysroot 和默认 <code>.pc</code> 搜索路径。</p><p>构建期间，<code>PKG_CONFIG_PATH</code> 以 <code>buildroot/lib/pkgconfig</code> 开头；StaticPHP 的依赖查询和生成的 CMake toolchain 文件都会请求 <code>--static</code> 参数。这样可以避免无关的系统库悄悄满足原本应由 StaticPHP 自行构建的依赖。</p><h2 id="package-构建-executor" tabindex="-1">Package 构建 Executor <a class="header-anchor" href="#package-构建-executor" aria-label="Permalink to “Package 构建 Executor”">​</a></h2><p>Package 类使用三种通用 Executor 实现：</p><table tabindex="0"><thead><tr><th>Executor</th><th>平台与构建系统</th><th>当前行为</th></tr></thead><tbody><tr><td><code>UnixAutoconfExecutor</code></td><td>Linux/macOS，Autoconf</td><td>添加静态/PIC 和 <code>buildroot</code> 前缀参数，执行 <code>configure</code>、并行 <code>make</code>，并可选执行 <code>make install</code></td></tr><tr><td><code>UnixCMakeExecutor</code></td><td>Linux/macOS，CMake</td><td>生成以 <code>buildroot</code> 为根的 toolchain 文件，固定使用 StaticPHP 的编译器和 pkg-config，禁用共享库，然后执行配置、构建和安装</td></tr><tr><td><code>WindowsCMakeExecutor</code></td><td>Windows，CMake/MSVC</td><td>使用 x64 Visual Studio generator、静态 MSVC runtime 和 StaticPHP CMake toolchain 文件，并执行 <code>cmake --build --target install</code></td></tr></tbody></table><p>Executor 会初始化 Package 专属的 include、library 和环境路径，并使用配置的构建并发数。Unix Autoconf 失败时会保留 <code>config.log</code>，Unix CMake Executor 会把可用的配置/错误/输出日志复制到 <code>SPC_LOGS_DIR</code>。Windows CMake Executor 当前依赖通用 shell 和 output 日志，不会另行收集这些 CMake 文件。</p><p>维护内置 Package 时，这些类是很有用的实现入口，但其构造函数和链式方法尚未被声明为稳定 PHP API。在公开扩展 API 定义完成前，Package 作者应遵循现有的 <code>src/Package/Library</code> 或 <code>src/Package/Tool</code> 实现模式。</p><h2 id="排查工具故障" tabindex="-1">排查工具故障 <a class="header-anchor" href="#排查工具故障" aria-label="Permalink to “排查工具故障”">​</a></h2><p>Doctor 已通过但某个 Package 仍构建失败时：</p><ol><li>运行 <code>spc dev:shell</code>（或 <code>bin/spc dev:shell</code>），检查 <code>CC</code>、<code>CXX</code>、<code>AR</code>、<code>LD</code>、<code>PKG_CONFIG</code> 和 <code>PATH</code>。</li><li>确认 <code>SPC_TARGET</code> 描述的是预期的 libc 和 ABI。</li><li>查看 <code>log/spc.output.log</code>、<code>log/spc.shell.log</code> 以及 Package 专属的 Autoconf/CMake 日志。</li><li>在 Windows 上，如果 Visual Studio、MSYS2 或 LLVM 组件发生变化，请重新运行 Doctor；只有怀疑 Visual Studio 环境缓存过期时，才删除有效期一小时的 <code>downloads/.vcenv-cache</code>。</li></ol><p>不要通过把二进制复制进 <code>buildroot/</code> 或修改生成的构建目录来绕过缺失工具。应根据工具的职责，把它加入宿主机前置依赖、StaticPHP 工具 Package 或 Package 构建依赖。</p>`,60)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};